  "rxiob": "Kabla ya kila kuhama, uliza:  bustani hiyo ilitishia nini? Baada ya kuhama, ni nani kati ya vipande vyangu asiyelindwa?",
  "1iwpe2z": "Kila zamu, tazama hundi, kuna picha na vitisho kwanza: kwa kawaida, mara nyingi kuna pigo la kushinda.",
  "qrpsfi": "Jifunze namna ya kujamiiana (namba ya nyuma, farasi wa Arabia, Boden, amesongwa sana...) ili uweze kuziona wakati wa mchezo.",
  "xhwanc": "Chukua kituo hicho, sitawisha mashujaa na maaskofu kwanza, ngome mapema, na usisonge kipande mara mbili bila uhitaji.",
  "1ulggiy": "Ngome kabla ya kuhamisha 10 na kuweka makarani wakimfunika mfalme wako; wakati mfalme adui angali katikati, fungua kituo na shambulio.",
  "1t15fl6": "Wakati hakuna mbinu: tafuta kitu chako kibaya zaidi, kipeleke kwenye uwanja bora zaidi, na uchukue faili wazi pamoja na keki zako.",
  "1fs9wy0": "Wakati ujao katika habari: kubadilishana vipande, mchukue mfalme wako na kusukuma kibandia kilichopita. Usikimbie haraka: Chunguza kila hatua unayochukua ili usifikiri kwamba uko tayari kufanya hivyo.",
