  "1pt5m6n": "Ni mara chache sana una tatizo:",
  "16dg98h": "Sikuelewa swali hilo wala sikupata makala inayofanana katika Maktaba ya Ujuzi. Jaribu dokezo lililo hapa chini, au neno fupi la msingi (kwa mfano: pini, lilipitishwa kwa miguu, Lucena).",
