  "268emb": "Ninahitaji angalau michezo 2 iliyochunguzwa na Stockfish kwa usahihi (unaotoa maelezo {0}). Cheza michezo mingine michache, au bonyeza habari",
  "88zp7f": "In {0} Michezo iliyochunguzwa, kisababishi kikubwa zaidi ni",
