  "1l3sbwk": "({0} makosa makubwa).",
  "8mpnu3": "({0} makosa makubwa). Mfano: songa mwaka wa {1} dhidi ya mwaka wa {2}, ulicheza dansi",
  "1bdq9xf": "At {0} Elo, orodha imara ambayo ni rahisi kujifunza:",
