  "vwl3ic": "Wastani wa usahihi {0}%.",
  "1t7sota": "Endelea kuwa na mazoea hayo mazuri na kukazia fikira {0}.",
  "sxkbb2": "Kwenda zake {0} kwa {1} Elo: (1) Dakika 10 1715 za mbinu za mafumbo kila siku, (2) kupitia kitabu Doform Notesbook kwa ukawaida, (3) kucheza michezo mirefu zaidi (jumu 10 au zaidi) dhidi ya {2} na kupitia kila hasara, (4) kutatua udhaifu wako mkubwa wa sasa:",
  "1763pgg": "Endgame: {0} inachanganua makosa makubwa {1}; michezo {2} ya kushinda haikushinda. {3}",
  "1gtjhew": "Ulikosa {0} mbinu na {1} Wachunguzi, na kuacha kipande ili kishinde {2} nyakati. {3}",
  "1dw79cf": "Ambatanisha makala zilizoandikwa, {0} Mafungu na sehemu za mwisho kutoka Maktaba hiyo, na vile vituo 20 vya kujifunzia.",
